0002622c: ac15a00f  or        %l6, 0xf, %l6
00026230: eca4c5e0  sta       %l6, [%l3] 0x2f                    ! pa 0xfe0001008 MSI M-to-S regs (AFSR/AFAR/arbiter/slot cfg) +0x8
00026234: e6800080  lda       [%g0] 0x04, %l3                    ! MCNTL: IMPL 1 = Ross; ASI_MMUREGS MMU control (PCR/MCNTL)
00026238: a734e01c  srl       %l3, 28, %l3
0002623c: 80a4e001  cmp       %l3, 1
00026240: 02800017  be        reset_ross_mid_setup
00026244: 01000000  nop
00026248: a6102300  mov       0x300, %l3                         ! = 0x00000300 (ROM)
0002624c: e684c080  lda       [%l3] 0x04, %l3                    ! SFSR bit 17: error mode (watchdog) reset; ASI_MMUREGS sync fault status (SFSR)
00026250: 29000080  sethi     %hi(0x00020000), %l4
00026254: 808cc014  andcc     %l3, %l4, %g0
00026258: 128000b0  bne       reset_is_watchdog
